    $seenIds = [];
    foreach ($manifest as $fingerprint => $entry) {
        if (!hash_equals(
            $fingerprint,
            ingredientOntologyV3CuratedProductReviewFingerprint($entry)
        )) {
            throw new LogicException(
                'curated product manifest fingerprint mismatch for product '
                . (int)$entry['expected_product_id']
            );
        }
        $productId = (int)$entry['expected_product_id'];
        if (isset($seenIds[$productId])) {
